import pytest
from fastapi.testclient import TestClient
from main import app, get_db, get_current_user

client = TestClient(app)

# Override authentication
def override_get_current_user():
    return {"id": 1, "username": "testuser", "role": "user"}
app.dependency_overrides[get_current_user] = override_get_current_user

# Override database
def override_get_db():
    # Use an in-memory SQLite session for tests
    ...
app.dependency_overrides[get_db] = override_get_db

def test_health():
    response = client.get("/health")
    assert response.status_code == 200
    assert response.json() == {"status": "ok"}

def test_get_authenticated_user():
    response = client.get("/users/me")
    assert response.status_code == 200
    assert response.json()["username"] == "testuser"

def test_create_user():
    user_data = {"email": "test@example.com", "username": "newuser", "password": "secret"}
    response = client.post("/users/", json=user_data)
    assert response.status_code == 200
    assert response.json()["email"] == "test@example.com"
